(function () {
  'use strict';

  var GA_ID = 'G-452MPHT894';
  var scriptSelector = 'script[src*="googletagmanager.com/gtag/js?id=' + GA_ID + '"]';

  function hasConfig() {
    var layer = window.dataLayer || [];
    return layer.some(function (entry) {
      return entry && entry[0] === 'config' && entry[1] === GA_ID;
    });
  }

  function ensureAnalytics() {
    window.dataLayer = window.dataLayer || [];
    if (typeof window.gtag !== 'function') {
      window.gtag = function () { window.dataLayer.push(arguments); };
    }

    if (!hasConfig()) {
      window.gtag('js', new Date());
      window.gtag('config', GA_ID);
    }

    if (!document.querySelector(scriptSelector)) {
      var script = document.createElement('script');
      script.async = true;
      script.src = 'https://www.googletagmanager.com/gtag/js?id=' + GA_ID;
      document.head.appendChild(script);
    }
  }

  function cleanText(value) {
    return String(value || '').replace(/\s+/g, ' ').trim().slice(0, 120);
  }

  function outfitIdFromPath(pathname) {
    var match = String(pathname || '').match(/\/outfits\/look-(\d+)/i);
    return match ? 'look-' + String(match[1]).padStart(2, '0') : '';
  }

  function send(name, params) {
    ensureAnalytics();
    var payload = Object.assign({ page_path: window.location.pathname }, params || {});
    window.gtag('event', name, payload);
  }

  window.acTrack = send;
  ensureAnalytics();

  function pathType(path) {
    if (path.indexOf('/outfits/') === 0) return 'outfit';
    if (path.indexOf('/style/') === 0) return 'style';
    if (path.indexOf('/blog/') === 0) return 'article';
    if (path.indexOf('/closet') === 0) return 'closet';
    return 'internal';
  }

  document.addEventListener('click', function (event) {
    var target = event.target;
    var reloadButton = target.closest && target.closest('.btn-reload, [data-ac-action="reload"]');
    if (reloadButton) {
      var maxScroll = Math.max(1, document.documentElement.scrollHeight - window.innerHeight);
      var reloadSource = reloadButton.getAttribute('data-reload-source') || (reloadButton.classList.contains('ac-header-reload') ? 'header' : 'page');
      send('reload_outfits', {
        control_text: cleanText(reloadButton.textContent),
        reload_source: reloadSource,
        scroll_depth: Math.max(0, Math.min(100, Math.round((window.scrollY / maxScroll) * 100)))
      });
    }

    var anchor = target.closest && target.closest('a[href]');
    if (!anchor) return;

    try {
      var url = new URL(anchor.href, window.location.href);
      var text = cleanText(anchor.textContent || anchor.getAttribute('aria-label'));
      var isFullOutfit = anchor.matches('[data-event="buy-full-outfit"], .btn-buy-full, .buy-full-outfit') || /mua\s*cả\s*set/i.test(text);
      var isShopee = /(^|\.)shopee\.vn$/i.test(url.hostname);
      var currentOutfitId = outfitIdFromPath(window.location.pathname);

      if (isFullOutfit) {
        send('click_buy_full_outfit', {
          outfit_id: currentOutfitId,
          link_url: url.href,
          link_text: text,
          transport_type: 'beacon'
        });
      } else if (isShopee) {
        var item = anchor.closest('.item-link, li');
        var itemName = item ? cleanText((item.querySelector('h3, strong') || {}).textContent || text) : text;
        var itemType = item ? cleanText((item.querySelector('p') || {}).textContent || '') : '';
        send('click_shopee_item', {
          outfit_id: currentOutfitId,
          item_name: itemName,
          item_type: itemType,
          item_role: item ? (item.getAttribute('data-item-role') || 'supporting') : 'unknown',
          item_position: item ? Number(item.getAttribute('data-item-position') || 0) : 0,
          link_url: url.href,
          transport_type: 'beacon'
        });
      }

      if (url.origin !== window.location.origin) return;
      var type = pathType(url.pathname);
      if (type === 'outfit') {
        var openedId = outfitIdFromPath(url.pathname);
        send('click_outfit', { outfit_id: openedId, link_url: url.pathname, link_text: text });
        send('open_outfit', { outfit_id: openedId, link_url: url.pathname, source_page: window.location.pathname });
        if (window.location.pathname.indexOf('/blog/') === 0 || window.location.pathname === '/blog.html') {
          send('click_blog_to_outfit', { outfit_id: openedId, link_url: url.pathname, source_article: window.location.pathname });
        }
      } else if (type === 'closet') {
        send('click_closet', { link_url: url.pathname });
      } else if (type === 'article') {
        send('click_related_article', { link_url: url.pathname, link_text: text });
      } else if (type === 'style') {
        var styleSlug = url.pathname.split('/').pop().replace(/\.html$/i, '');
        send('select_style', { style: styleSlug, link_url: url.pathname, link_text: text });
      }
    } catch (error) {
      // Invalid URLs should never block navigation.
    }
  });

  var blogSearch = document.getElementById('post-search');
  if (blogSearch) {
    var searchTimer = 0;
    var lastTrackedQuery = '';
    blogSearch.addEventListener('input', function () {
      window.clearTimeout(searchTimer);
      var query = cleanText(blogSearch.value).toLocaleLowerCase('vi');
      searchTimer = window.setTimeout(function () {
        if (query.length >= 2 && query !== lastTrackedQuery) {
          lastTrackedQuery = query;
          send('search_blog', { search_term: query });
        }
      }, 700);
    });
  }

  var fired50 = false;
  var fired90 = false;
  function scrollDepth() {
    var doc = document.documentElement;
    var max = Math.max(1, doc.scrollHeight - window.innerHeight);
    var pct = Math.round((window.scrollY / max) * 100);
    if (pct >= 50 && !fired50) {
      fired50 = true;
      send('article_scroll_50');
    }
    if (pct >= 90 && !fired90) {
      fired90 = true;
      send('article_scroll_90');
    }
  }
  if (window.location.pathname.indexOf('/blog/') === 0) {
    window.addEventListener('scroll', scrollDepth, { passive: true });
    scrollDepth();
  }
}());
